import React from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom'; 

// Importaciones de los componentes de autenticación y catálogo
import LoginRegister from './componentes/LoginRegister';
import BookCatalog from './componentes/BookCatalog';         

// Importación del componente de Administración
import AccountManagement from './componentes/AccountManagement'; // ¡Nuevo componente para el Admin!
import BookRegistration from './componentes/BookRegistration';

import './estilos/LoginRegister.css';


// Componentes Placeholder/Dummy (para las otras vistas)
const LibrarianDashboard = () => (
  <div style={{ padding: '20px', textAlign: 'center' }}>
    <h1>Dashboard de Bibliotecario </h1>
    <p>¡Hola Bibliotecario! Aquí se mostrará el panel principal. El registro de libros está en la ruta <code>/librarian/register-book</code>.</p>
  </div>
);


function App() {
  return (
    <BrowserRouter> 
      <div className="App">
        <Routes>
          
          {/* 1. RUTA DE INICIO DE SESIÓN */}
          <Route path="/" element={<LoginRegister />} /> 

          {/* 2. RUTA PARA ESTUDIANTES (Catálogo) */}
          <Route path="/bookcatalog" element={<BookCatalog />} /> 

          {/* 3. RUTA PRINCIPAL PARA ADMINISTRADOR (Gestión de Cuentas) */}
          {/* El dashboard del Admin ahora es el componente de gestión de cuentas */}
          <Route 
            path="/admin/dashboard" 
            element={<AccountManagement />} // <- El administrador accede directamente a AccountManagement
          />

          {/* 4. RUTAS PARA BIBLIOTECARIO (Registro de Libros) */}
          <Route path="/librarian/dashboard" element={<LibrarianDashboard />} />
          <Route path="/librarian/register-book" element={<BookRegistration />} />
          
          {/* 5. FALLBACK */}
          <Route path="*" element={<p style={{ textAlign: 'center', marginTop: '50px' }}>Página no encontrada (404)</p>} />
          
        </Routes>
      </div>
    </BrowserRouter>
  );
}

export default App;
